Write the output of the following program: 
#include<stdio.h> 
void main() { int num[5] = {3, 4, 6, 2, 1}; int *p = num; int* q = num+2; int* r = &num[1]; printf("
%d %d", num[2], *(num+2)); printf("
%d %d", *p, *(p+1)); printf("
%d %d", *q, *(q+1)); printf("
%d %d", *r, *(r+1)); 
}

Explain the functionality of the following recursive function.  int foo(int x, int y)   
{  
  if(x == 0)   return y;     
else      
   return foo(x – 1,x +y);   
}
